// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address actor, uint256 d, uint256 a) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        d = bound(d, 1, 1e30);
        a = bound(a, 1, d);

        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();

        vm.prank(actor);
        try c.withdraw(a) {
            // withdrawal succeeded
        } catch {
            return; // out of admissible domain if the reference reverts here
        }

        vm.prank(actor);
        bool ok;
        try c.refund() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
